"""(v14: clone of hexn_lattice_gen_v13.py, left untouched; instantiates hexn_bank_v15 and adds the port leak_sh. Modules are named hexn_lattice_<shape>_v14.)"""
"""(v12: clone of hexn_lattice_gen_v11.py, left untouched; instantiates hexn_bank_v15 (cell forward total through a port). Modules are named hexn_lattice_<shape>_v14.)"""
"""(v11: clone of hexn_lattice_gen_v10.py, left untouched; instantiates hexn_bank_v15 (cell mode: glue buffer and one full cell behind the detectors); the lattice module gains the ports cell_mode, lane_cfg, cell_thr, cell_cnt, cell_fwd, cap_flat. Modules are named hexn_lattice_<shape>_v14.)"""
"""(v10: clone of hexn_lattice_gen_v9.py, left untouched; instantiates hexn_bank_v15 (no feedback phase). Modules are named hexn_lattice_<shape>_v14.)"""
"""(v9: clone of hexn_lattice_gen_v8.py, left untouched. WIDE INPUT: NB wires (default 18) in three groups of NB/3 (A, B, C along the three line directions); each bridge register is NB/3 bits wide. Usage: hexn_lattice_gen_v14.py SHAPE [NB] [AW]. Modules are named hexn_lattice_<shape>_v14 with defaults NB, AW as given.) (v2: the same plus debug outputs for the trained settings; modules are named hexn_lattice_<shape>_v2.) Generate the Verilog of a Hex-N 12-wire detector bank on the hex lattice with edge bridges (layout: tools/hexn_lattice_v1.py). Usage: hexn_lattice_gen_v14.py SHAPE > rtl/gen/hexn_lattice_SHAPE_v14.v
The module has the same ports and parameters as hexn_bank_v1 (K = cells of the shape, NB = 12). Class k = cell k (order of the shape). Each bridge is a 4-bit register; the first bridge of a line takes its group straight from s_bits."""
import sys, os, importlib.util
sp = importlib.util.spec_from_file_location("lat", os.path.join(os.path.dirname(os.path.abspath(__file__)), "hexn_lattice_v1.py")); lat = importlib.util.module_from_spec(sp); sp.loader.exec_module(lat)
name = sys.argv[1]; NBW = int(sys.argv[2]) if len(sys.argv) > 2 else 18; AWD = int(sys.argv[3]) if len(sys.argv) > 3 else 7; G = NBW // 3; assert NBW % 3 == 0; cells = lat.shape(name); idx, br = lat.layout(cells); K = len(cells); settle = max(v["pos"] for v in br.values()) + 1
bid = {k: i for i, k in enumerate(sorted(br, key=lambda k: (idx[k[0]], k[1])))}
o = []
o.append("`default_nettype none")
o.append(f"// Generated by tools/hexn_lattice_gen_v14.py {name}: {K} detectors on a hex lattice, {len(br)} edge bridges (3 per cell, {G} flip-flops each), settle {settle} clocks. DO NOT EDIT; regenerate.")
o.append(f"module hexn_lattice_{name}_v14 #(parameter K = {K}, parameter NB = {NBW}, parameter AW = {AWD}, parameter S = 16, parameter CB = 6, parameter ACCMODE = 0, parameter NC = 1) (")
o.append("    input  wire clk, input wire rst, input wire tr_start, input wire [2:0] tr_cmd, output wire tr_busy,")
o.append("    input  wire [NB-1:0] s_bits, input wire [$clog2(K)-1:0] s_label, input wire [CB-1:0] t_in,")
o.append("    input  wire run_start, output wire run_busy, output wire run_done, output wire ans_valid, output wire [$clog2(K)-1:0] ans_class, output wire [4*K-1:0] cnt_flat, input wire cell_mode, input wire [2:0] leak_sh, input wire [NC*2*K-1:0] lane_cfg, input wire [NC*AW-1:0] cell_thr, output wire [NC*5-1:0] cell_cnt, output wire [NC*AW-1:0] cell_fwd, output wire [3*K-1:0] cap_flat,")
o.append("    output wire [K*NB-1:0] dbg_wpos, output wire [K*NB-1:0] dbg_wneg, output wire [K*AW-1:0] dbg_thr, output wire [K*16-1:0] dbg_sump, output wire [K*16-1:0] dbg_sumn, output wire [K*8-1:0] dbg_net, output wire [K*8-1:0] dbg_fwd, input wire [$clog2(K*NB+1)-1:0] cap_ad, output wire [7:0] cap_data, output wire [15:0] cap_n, input wire [$clog2(K*NB+1)-1:0] peek_ad, output wire signed [CB-1:0] peek_data);")
o.append(f"    reg [{G-1}:0] bridge [0:{len(br)-1}];")
o.append("    always @(posedge clk) begin")
for k, b in sorted(bid.items(), key=lambda x: x[1]):
    src = f"s_bits[{G*k[1]} +: {G}]" if br[k]["up"] is None else f"bridge[{bid[br[k]['up']]}]"
    o.append(f"        bridge[{b}] <= {src};   // cell {idx[k[0]]} {k[0]} group {'ABC'[k[1]]} (line position {br[k]['pos']})")
o.append("    end")
o.append("    wire [K*NB-1:0] rx_flat;")
for c in cells:
    i = idx[c]; o.append(f"    assign rx_flat[{i}*NB +: NB] = {{bridge[{bid[(c,2)]}], bridge[{bid[(c,1)]}], bridge[{bid[(c,0)]}]}};   // cell {i} {c}")
o.append(f"    hexn_bank_v15 #(.K(K), .NB(NB), .AW(AW), .S(S), .CB(CB), .SETTLE({settle}), .ACCMODE(ACCMODE), .NC(NC)) bank(.clk(clk), .rst(rst), .tr_start(tr_start), .tr_cmd(tr_cmd), .tr_busy(tr_busy), .s_bits(s_bits), .rx_flat(rx_flat), .s_label(s_label), .t_in(t_in),")
o.append("        .run_start(run_start), .run_busy(run_busy), .run_done(run_done), .ans_valid(ans_valid), .ans_class(ans_class), .cnt_flat(cnt_flat), .cell_mode(cell_mode), .leak_sh(leak_sh), .lane_cfg(lane_cfg), .cell_thr(cell_thr), .cell_cnt(cell_cnt), .cell_fwd(cell_fwd), .cap_flat(cap_flat), .dbg_wpos(dbg_wpos), .dbg_wneg(dbg_wneg), .dbg_thr(dbg_thr), .dbg_sump(dbg_sump), .dbg_sumn(dbg_sumn), .dbg_net(dbg_net), .dbg_fwd(dbg_fwd), .cap_ad(cap_ad), .cap_data(cap_data), .cap_n(cap_n), .peek_ad(peek_ad), .peek_data(peek_data));")
o.append("endmodule"); o.append("`default_nettype wire")
print("\n".join(o))
